const path = require('node:path')

// Use the already-loaded runtime, never load a second Node-RED instance.
function runtimeFlowAccess (RED) {
  const embedded = RED.settings.R
  let api = RED.runtime?.flows || (RED.server && embedded?.server === RED.server ? embedded.runtime?.flows : null)
  if (!api) {
    try {
      const resolved = require.resolve('@node-red/runtime', {
        paths: [RED.settings.coreNodesDir, RED.settings.userDir,
          path.dirname(require.main?.filename || __filename)].filter(Boolean)
      })
      const runtime = require.cache[resolved]?.exports
      if ((RED.server && runtime?.server === RED.server) || (RED.events && runtime?.events === RED.events)) api = runtime.flows
    } catch (_) {}
  }
  if (typeof api?.getFlows !== 'function' || typeof api?.setFlows !== 'function') return null
  return {
    async getSnapshot () {
      const snapshot = await api.getFlows({})
      if (typeof snapshot?.rev !== 'string' || !Array.isArray(snapshot.flows)) throw Error('Invalid runtime Flow snapshot')
      return structuredClone(snapshot)
    },
    setSnapshot (snapshot) {
      return api.setFlows({ flows: snapshot, deploymentType: 'nodes' })
    }
  }
}

module.exports = { runtimeFlowAccess }
